//! Transform handles, resize and rotation parity (ex-508).
//!
//! `tests/fixtures/transform.json` is upstream's own
//! `packages/element/src/transformHandles.ts`, `resizeTest.ts` and
//! `resizeElements.ts` at the pinned commit, generated by
//! `tools/goldens/transform-fixtures.mjs`: handle layouts for every element
//! kind, pointer type, zoom and omitted-sides set; `resizeTest` and the
//! other hit tests on probes around every handle and side; cursors;
//! `hasBoundingBox`; `getResizeOffsetXY`; and pointer gestures driven the
//! way `App.tsx` drives `transformElements` (the scenes of upstream's
//! `resize.test.tsx`, rotations, sticky notes, bound and elbow arrows,
//! groups, frames, zoom and seeded random scenes). Every gesture step is
//! replayed and the whole scene compared with upstream's, number for
//! number.
//!
//! The calls `transformElements` makes into binding (`updateBoundElements`)
//! and sticky-note layout (`getStickyNoteLayout`, ex-703) are recorded in
//! the fixture with their arguments and effects. The test's
//! [`TransformEnv`] checks each call's arguments; a binding call is then
//! run by the port's own `updateBoundElements`
//! ([`excali_editor::binding::update_bound_elements`]) and every element it
//! changes compared with what upstream's changed, and a sticky-note layout
//! is answered with what upstream returned.
//!
//! The tests after the replay restate `resize.test.tsx`'s assertions on
//! those gestures.

use std::collections::{HashSet, VecDeque};

use excali_core::element::Element;
use excali_editor::binding::{update_bound_elements, BindingEnv};
use excali_editor::resize_elements::{
    get_resize_arrow_direction, get_resize_offset_xy, resize_single_element, ArrowDirection,
    ResizeOptions, StickyNoteLayout, StickyNoteLayoutAnchor, StickyNoteLayoutOpts,
    StickyNoteTextLayout, TransformEnv,
};
use excali_editor::resize_test::{
    get_cursor_for_resizing_element, get_element_with_transform_handle_type,
    get_transform_handle_type_from_coords, resize_test,
};
use excali_editor::scene::{MutationEnv, Scene};
use excali_editor::tools::PointerType;
use excali_editor::transform::{TransformModifiers, TransformSession};
use excali_editor::transform_handles::{
    get_transform_handles, get_transform_handles_from_coords, has_bounding_box, EditorInterface,
    FormFactor, OmitSides, SelectedLinearElementState, TransformHandleDirection,
    TransformHandleType, TransformHandles, DEFAULT_OMIT_SIDES, OMIT_SIDES_FOR_FRAME,
};
use excali_scene::bounds::ElementsMap;
use excali_text::text_measurements::{CharCountTextMetrics, CharWidthCache, TextMetricsProvider};
use serde_json::{Map, Value};

const FIXTURE: &str = include_str!("fixtures/transform.json");

fn cases() -> Vec<Value> {
    let fixture: Value = serde_json::from_str(FIXTURE).expect("transform.json parses");
    fixture["cases"].as_array().expect("cases").clone()
}

fn case(id: &str) -> Value {
    cases()
        .into_iter()
        .find(|c| c["id"] == id)
        .unwrap_or_else(|| panic!("no case {id}"))
}

fn element(value: &Value) -> Element {
    Element::from_map(value.as_object().expect("an element").clone())
        .expect("an element upstream built")
}

fn elements(value: &Value) -> Vec<Element> {
    value
        .as_array()
        .expect("elements")
        .iter()
        .map(element)
        .collect()
}

fn num(v: &Value) -> f64 {
    v.as_f64().unwrap_or_else(|| panic!("a number, got {v}"))
}

fn point(v: &Value) -> [f64; 2] {
    [num(&v[0]), num(&v[1])]
}

fn pointer_type(v: &Value) -> PointerType {
    match v.as_str().expect("pointer type") {
        "mouse" => PointerType::Mouse,
        "pen" => PointerType::Pen,
        "touch" => PointerType::Touch,
        other => panic!("pointer type {other}"),
    }
}

fn editor(v: &Value) -> EditorInterface {
    match v.as_str().expect("editor") {
        "desktop" => EditorInterface::new(FormFactor::Desktop, false),
        "phone-mobile" => EditorInterface::new(FormFactor::Phone, true),
        "phone-desktop-agent" => EditorInterface::new(FormFactor::Phone, false),
        "tablet-mobile" => EditorInterface::new(FormFactor::Tablet, true),
        other => panic!("editor {other}"),
    }
}

/// A begin step's `appState.selectedLinearElement` (`null`, or its
/// `isEditing` and `hoverPointIndex`).
fn selected_linear_element(v: &Value) -> Option<SelectedLinearElementState> {
    if v.is_null() {
        return None;
    }
    Some(SelectedLinearElementState {
        is_editing: v["isEditing"] == true,
        hover_point_index: v["hoverPointIndex"].as_i64().expect("hoverPointIndex"),
        ..SelectedLinearElementState::default()
    })
}

fn omit_sides(v: &Value) -> OmitSides {
    match v.as_str().expect("omit sides") {
        "default" | "desktop" => DEFAULT_OMIT_SIDES,
        "none" => OmitSides::default(),
        "frame" => OMIT_SIDES_FOR_FRAME,
        "corners" => OmitSides {
            nw: true,
            se: true,
            rotation: true,
            ..OmitSides::default()
        },
        other => panic!("omit sides {other}"),
    }
}

/// The handle upstream answered: a string, or `false` for none.
fn handle_type(v: &Value) -> Option<TransformHandleType> {
    match v {
        Value::Bool(false) => None,
        Value::String(s) => Some(TransformHandleType::parse(s).unwrap_or_else(|| panic!("{s}"))),
        other => panic!("a handle, got {other}"),
    }
}

fn direction(v: &Value) -> TransformHandleDirection {
    TransformHandleDirection::parse(v.as_str().expect("a direction")).expect("a direction")
}

fn handles_json(handles: &TransformHandles) -> Map<String, Value> {
    handles
        .iter()
        .map(|(kind, h)| {
            (
                kind.as_str().to_string(),
                Value::Array(h.iter().map(|&n| Value::from(n)).collect()),
            )
        })
        .collect()
}

fn same_handles(actual: &TransformHandles, expected: &Value, context: &str) {
    let expected = expected.as_object().expect("handles");
    let actual = handles_json(actual);
    let mut expected_keys: Vec<&String> = expected.keys().collect();
    let mut actual_keys: Vec<&String> = actual.keys().collect();
    expected_keys.sort();
    actual_keys.sort();
    assert_eq!(actual_keys, expected_keys, "{context}: handle set");
    for (key, e) in expected {
        let a = &actual[key];
        for i in 0..4 {
            assert_eq!(num(&a[i]), num(&e[i]), "{context}: {key}[{i}]");
        }
    }
}

// -- JSON comparison --------------------------------------------------------------

/// Two numbers as the same double.
///
/// Exact: `excali_math::js` computes `Math.sin`, `Math.cos` and
/// `Math.atan2` as Node 26's V8 does (ADR-011), so a rotated element's
/// numbers are upstream's to the last bit. `-0` and `0` are one number
/// (`==`), as `JSON.stringify` writes them.
fn same_number(a: f64, e: f64) -> bool {
    a == e
}

/// Upstream's element and the port's, key for key and number for number
/// ([`same_number`]; `-0` and `0` are one number, as `JSON.stringify`
/// writes them). `versionNonce` and `updated` come from upstream's random
/// generator and clock and are not compared.
fn same_json(actual: &Value, expected: &Value, path: &str) -> Result<(), String> {
    match (actual, expected) {
        (Value::Number(a), Value::Number(e)) => {
            let (a, e) = (a.as_f64().expect("f64"), e.as_f64().expect("f64"));
            if same_number(a, e) {
                Ok(())
            } else {
                Err(format!("{path}: {a} != {e} (expected)"))
            }
        }
        (Value::Array(a), Value::Array(e)) => {
            if a.len() != e.len() {
                return Err(format!(
                    "{path}: {} items != {} (expected)",
                    a.len(),
                    e.len()
                ));
            }
            for (i, (a, e)) in a.iter().zip(e).enumerate() {
                same_json(a, e, &format!("{path}[{i}]"))?;
            }
            Ok(())
        }
        (Value::Object(a), Value::Object(e)) => {
            for key in e.keys().chain(a.keys()) {
                if key == "versionNonce" || key == "updated" {
                    continue;
                }
                match (a.get(key), e.get(key)) {
                    (Some(av), Some(ev)) => same_json(av, ev, &format!("{path}.{key}"))?,
                    (None, Some(ev)) => {
                        return Err(format!("{path}.{key}: missing, expected {ev}"))
                    }
                    (Some(av), None) => return Err(format!("{path}.{key}: {av}, expected no key")),
                    (None, None) => unreachable!(),
                }
            }
            Ok(())
        }
        (a, e) if a == e => Ok(()),
        (a, e) => Err(format!("{path}: {a} != {e} (expected)")),
    }
}

// -- the environment ------------------------------------------------------------------

/// Text measured as upstream's tests measure it; the hooks answered from
/// the fixture.
#[derive(Default)]
struct ReplayEnv {
    char_widths: CharWidthCache,
    hooks: VecDeque<Value>,
    context: String,
}

impl MutationEnv for ReplayEnv {
    fn random_integer(&mut self) -> f64 {
        0.0
    }
    fn now(&mut self) -> f64 {
        1.0
    }
}

fn opt_num(v: &Value) -> Option<f64> {
    if v.is_null() {
        None
    } else {
        Some(num(v))
    }
}

impl BindingEnv for ReplayEnv {
    fn text(&mut self) -> (&dyn TextMetricsProvider, &mut CharWidthCache) {
        (&CharCountTextMetrics, &mut self.char_widths)
    }
}

impl TransformEnv for ReplayEnv {
    fn update_bound_elements(
        &mut self,
        scene: &mut Scene,
        changed: &str,
        simultaneously_updated: Option<&[String]>,
    ) {
        let hook = self.hooks.pop_front().unwrap_or_else(|| {
            panic!(
                "{}: updateBoundElements({changed}) not called upstream",
                self.context
            )
        });
        assert_eq!(
            hook["hook"], "updateBoundElements",
            "{}: hook order",
            self.context
        );
        assert_eq!(
            hook["changed"], changed,
            "{}: updateBoundElements element",
            self.context
        );
        let expected: Option<Vec<String>> = hook["simultaneouslyUpdated"].as_array().map(|ids| {
            ids.iter()
                .map(|id| id.as_str().expect("an id").to_string())
                .collect()
        });
        assert_eq!(
            simultaneously_updated.map(<[String]>::to_vec),
            expected,
            "{}: updateBoundElements simultaneouslyUpdated",
            self.context
        );
        // updateBoundElements run by the port, its effect compared with
        // upstream's: the elements upstream changed as upstream left them,
        // every other element as it was
        let before: Vec<Element> = scene.elements().to_vec();
        let context = format!("{}: updateBoundElements({changed})", self.context);
        update_bound_elements(scene, self, changed, simultaneously_updated, None);
        let changes: Vec<&Value> = hook["changes"]
            .as_array()
            .expect("changes")
            .iter()
            .collect();
        assert_eq!(
            scene.elements().len(),
            before.len(),
            "{context}: element count"
        );
        for (actual, prior) in scene.elements().iter().zip(&before) {
            let id = actual.base.id.as_str();
            match changes.iter().find(|c| c["id"] == id) {
                Some(expected) => {
                    let actual = Value::Object(actual.to_map());
                    same_json(&actual, expected, &format!("{context} {id}")).unwrap_or_else(|e| {
                        panic!("{e}\n  port:     {actual}\n  upstream: {expected}")
                    });
                }
                // as JSON: a NaN (written null) is the NaN it was
                None => assert_eq!(
                    Value::Object(actual.to_map()),
                    Value::Object(prior.to_map()),
                    "{context}: {id} changed, upstream left it"
                ),
            }
        }
    }

    fn sticky_note_layout(
        &mut self,
        container: &Element,
        text: Option<&Element>,
        opts: &StickyNoteLayoutOpts,
    ) -> StickyNoteLayout {
        let hook = self
            .hooks
            .pop_front()
            .unwrap_or_else(|| panic!("{}: getStickyNoteLayout not called upstream", self.context));
        assert_eq!(
            hook["hook"], "stickyNoteLayout",
            "{}: hook order",
            self.context
        );
        let ctx = format!("{}: getStickyNoteLayout argument", self.context);
        same_json(
            &Value::Object(container.to_map()),
            &hook["container"],
            &format!("{ctx} container"),
        )
        .unwrap_or_else(|e| panic!("{e}"));
        match text {
            Some(text) => same_json(
                &Value::Object(text.to_map()),
                &hook["text"],
                &format!("{ctx} text"),
            )
            .unwrap_or_else(|e| panic!("{e}")),
            None => assert!(hook["text"].is_null(), "{ctx}: text"),
        }
        let o = &hook["opts"];
        assert_eq!(
            opts.base_height,
            opt_num(&o["baseHeight"]),
            "{ctx}: baseHeight"
        );
        assert_eq!(
            opts.base_font_size,
            opt_num(&o["baseFontSize"]),
            "{ctx}: baseFontSize"
        );
        let anchor = o["anchor"].as_str().map(|a| match a {
            "top" => StickyNoteLayoutAnchor::Top,
            "center" => StickyNoteLayoutAnchor::Center,
            "bottom" => StickyNoteLayoutAnchor::Bottom,
            other => panic!("anchor {other}"),
        });
        assert_eq!(opts.anchor, anchor, "{ctx}: anchor");
        let r = &hook["result"];
        let c = &r["container"];
        StickyNoteLayout {
            x: num(&c["x"]),
            y: num(&c["y"]),
            width: num(&c["width"]),
            height: num(&c["height"]),
            base_height: num(&c["baseHeight"]),
            text: if r["text"].is_null() {
                None
            } else {
                let t = &r["text"];
                Some(StickyNoteTextLayout {
                    text: t["text"].as_str().expect("text").to_string(),
                    font_size: num(&t["fontSize"]),
                    base_font_size: num(&t["baseFontSize"]),
                    width: num(&t["width"]),
                    height: num(&t["height"]),
                    x: num(&t["x"]),
                    y: num(&t["y"]),
                    angle: num(&t["angle"]),
                })
            },
        }
    }
}

// -- session replay -------------------------------------------------------------------

fn apply_changes(expected: &mut [Value], changed: &Value) {
    for change in changed.as_array().expect("changed") {
        let slot = expected
            .iter_mut()
            .find(|e| e["id"] == change["id"])
            .expect("a changed element is in the scene");
        *slot = change.clone();
    }
}

fn compare_scene(scene: &Scene, expected: &[Value], context: &str) {
    assert_eq!(
        scene.elements().len(),
        expected.len(),
        "{context}: element count"
    );
    for (actual, expected) in scene.elements().iter().zip(expected) {
        let actual = Value::Object(actual.to_map());
        let id = &expected["id"];
        same_json(&actual, expected, &format!("{context} {id}"))
            .unwrap_or_else(|e| panic!("{e}\n  port:     {actual}\n  upstream: {expected}"));
    }
}

fn ids(v: &Value) -> Vec<String> {
    v.as_array()
        .expect("ids")
        .iter()
        .map(|id| id.as_str().expect("an id").to_string())
        .collect()
}

/// Replays one session case; returns the scene after every step.
fn replay(case: &Value) -> Vec<Vec<Value>> {
    let id = case["id"].as_str().expect("id");
    let mut expected: Vec<Value> = case["elements"].as_array().expect("elements").clone();
    let mut scene = Scene::new(elements(&case["elements"]));
    let mut env = ReplayEnv::default();
    let mut session: Option<TransformSession> = None;
    let mut snapshot: Option<Vec<Element>> = None;
    let mut states = Vec::new();
    for (n, step) in case["steps"].as_array().expect("steps").iter().enumerate() {
        let context = format!("{id} step {n} ({})", step["type"]);
        env.context = context.clone();
        match step["type"].as_str().expect("type") {
            "begin" => {
                let s = TransformSession::begin(
                    &scene,
                    &ids(&step["selected"]),
                    point(&step["origin"]),
                    num(&step["zoom"]),
                    pointer_type(&step["pointerType"]),
                    &editor(&step["editor"]),
                    selected_linear_element(&step["selectedLinearElement"]),
                );
                let r = &step["result"];
                assert_eq!(s.handle(), handle_type(&r["handle"]), "{context}: handle");
                for (what, actual, expected) in [
                    ("offset", s.offset(), point(&r["offset"])),
                    ("center", s.center(), point(&r["center"])),
                ] {
                    assert!(
                        same_number(actual[0], expected[0]) && same_number(actual[1], expected[1]),
                        "{context}: {what} {actual:?} != {expected:?}"
                    );
                }
                let arrow_direction = match r["arrowDirection"].as_str().expect("direction") {
                    "origin" => ArrowDirection::Origin,
                    _ => ArrowDirection::End,
                };
                assert_eq!(
                    s.arrow_direction(),
                    arrow_direction,
                    "{context}: arrow direction"
                );
                env.char_widths = CharWidthCache::new();
                session = Some(s);
            }
            "move" => {
                env.hooks = step["hooks"]
                    .as_array()
                    .expect("hooks")
                    .iter()
                    .cloned()
                    .collect();
                let result = session.as_ref().expect("a gesture").update(
                    &mut scene,
                    &mut env,
                    point(&step["point"]),
                    TransformModifiers {
                        shift: step["shift"] == true,
                        alt: step["alt"] == true,
                        ctrl: step["ctrl"] == true,
                    },
                    opt_num(&step["gridSize"]),
                );
                assert_eq!(
                    result,
                    step["result"] == true,
                    "{context}: transformElements result"
                );
                assert!(
                    env.hooks.is_empty(),
                    "{context}: hooks upstream made that the port did not: {:?}",
                    env.hooks
                );
                apply_changes(&mut expected, &step["changed"]);
                compare_scene(&scene, &expected, &context);
            }
            "snapshot" => {
                snapshot = Some(scene.non_deleted().into_iter().cloned().collect());
                env.char_widths = CharWidthCache::new();
            }
            "resizeSingle" => {
                env.hooks = step["hooks"]
                    .as_array()
                    .expect("hooks")
                    .iter()
                    .cloned()
                    .collect();
                let originals: Vec<Element> = if step["orig"] == "snapshot" {
                    snapshot.clone().expect("a snapshot")
                } else {
                    env.char_widths = CharWidthCache::new();
                    scene.non_deleted().into_iter().cloned().collect()
                };
                let options = &step["options"];
                resize_single_element(
                    num(&step["nextWidth"]),
                    num(&step["nextHeight"]),
                    step["target"].as_str().expect("target"),
                    &originals,
                    &mut scene,
                    &mut env,
                    direction(&step["handle"]),
                    ResizeOptions {
                        should_maintain_aspect_ratio: options["shouldMaintainAspectRatio"] == true,
                        should_resize_from_center: options["shouldResizeFromCenter"] == true,
                    },
                );
                assert!(
                    env.hooks.is_empty(),
                    "{context}: hooks upstream made that the port did not"
                );
                apply_changes(&mut expected, &step["changed"]);
                compare_scene(&scene, &expected, &context);
            }
            other => panic!("{context}: step {other}"),
        }
        states.push(expected.clone());
    }
    states
}

// -- fixture replay -------------------------------------------------------------------

#[test]
fn fixture_covers_every_kind_and_hook() {
    let cases = cases();
    let kinds: HashSet<&str> = cases
        .iter()
        .map(|c| c["kind"].as_str().expect("kind"))
        .collect();
    for kind in [
        "handles",
        "handlesFromCoords",
        "resizeTest",
        "handleTypeFromCoords",
        "cursor",
        "hasBoundingBox",
        "resizeOffset",
        "session",
    ] {
        assert!(kinds.contains(kind), "no {kind} case");
    }
    let mut hooks = HashSet::new();
    let mut handles = HashSet::new();
    let mut types = HashSet::new();
    for c in cases.iter().filter(|c| c["kind"] == "session") {
        for e in c["elements"].as_array().expect("elements") {
            types.insert(e["type"].as_str().expect("type").to_string());
        }
        for s in c["steps"].as_array().expect("steps") {
            if s["type"] == "begin" {
                handles.insert(s["result"]["handle"].to_string());
            }
            for h in s["hooks"].as_array().into_iter().flatten() {
                let with_changes = h["changes"].as_array().is_some_and(|c| !c.is_empty());
                hooks.insert(format!(
                    "{}{}",
                    h["hook"],
                    if with_changes { "+" } else { "" }
                ));
            }
        }
    }
    for h in [
        "\"updateBoundElements\"",
        "\"updateBoundElements\"+",
        "\"stickyNoteLayout\"",
    ] {
        assert!(hooks.contains(h), "no {h} hook");
    }
    for h in ["n", "s", "w", "e", "nw", "ne", "sw", "se", "rotation"] {
        assert!(handles.contains(&format!("\"{h}\"")), "no gesture on {h}");
    }
    for t in [
        "rectangle",
        "diamond",
        "ellipse",
        "image",
        "text",
        "line",
        "arrow",
        "freedraw",
        "stickynote",
        "frame",
        "magicframe",
    ] {
        assert!(types.contains(t), "no gesture on a {t}");
    }
}

#[test]
fn transform_handles_match_upstream() {
    for case in cases().iter().filter(|c| c["kind"] == "handles") {
        let id = case["id"].as_str().expect("id");
        let scene = elements(&case["elements"]);
        let map = ElementsMap::new(&scene);
        let target = scene
            .iter()
            .find(|e| e.base.id == case["target"].as_str().expect("target"))
            .expect("target");
        for v in case["variants"].as_array().expect("variants") {
            let handles = get_transform_handles(
                target,
                num(&v["zoom"]),
                &map,
                pointer_type(&v["pointerType"]),
                &omit_sides(&v["omitSides"]),
            );
            same_handles(
                &handles,
                &v["result"],
                &format!(
                    "{id} zoom {} {} omit {}",
                    v["zoom"], v["pointerType"], v["omitSides"]
                ),
            );
        }
    }
}

#[test]
fn transform_handles_from_coords_match_upstream() {
    let case = case("handles-from-coords");
    for (i, v) in case["variants"]
        .as_array()
        .expect("variants")
        .iter()
        .enumerate()
    {
        let c = v["coords"].as_array().expect("coords");
        let coords = [
            num(&c[0]),
            num(&c[1]),
            num(&c[2]),
            num(&c[3]),
            num(&c[4]),
            num(&c[5]),
        ];
        let handles = get_transform_handles_from_coords(
            coords,
            num(&v["angle"]),
            num(&v["zoom"]),
            pointer_type(&v["pointerType"]),
            // getTransformHandlesFromCoords' own default is `{}`
            &if v["omitSides"] == "default" {
                OmitSides::default()
            } else {
                omit_sides(&v["omitSides"])
            },
            opt_num(&v["margin"]),
            opt_num(&v["spacing"]),
        );
        same_handles(&handles, &v["result"], &format!("variant {i}"));
    }
}

#[test]
fn resize_test_matches_upstream() {
    for case in cases().iter().filter(|c| c["kind"] == "resizeTest") {
        let id = case["id"].as_str().expect("id");
        let scene = elements(&case["elements"]);
        let map = ElementsMap::new(&scene);
        let refs: Vec<&Element> = scene.iter().collect();
        for v in case["variants"].as_array().expect("variants") {
            let selected: HashSet<String> = ids(if v["selected"].is_array() {
                &v["selected"]
            } else {
                &case["selected"]
            })
            .into_iter()
            .collect();
            let zoom = num(&v["zoom"]);
            let pointer = pointer_type(&v["pointerType"]);
            let editor = editor(&v["editor"]);
            for p in v["probes"].as_array().expect("probes") {
                let [x, y] = point(&p["point"]);
                let context = format!("{id} zoom {zoom} {pointer:?} {} at [{x}, {y}]", v["editor"]);
                for e in &scene {
                    let expected = handle_type(&p["results"][&e.base.id]);
                    let actual = resize_test(e, &map, &selected, x, y, zoom, pointer, &editor);
                    assert_eq!(actual, expected, "{context}: resizeTest({})", e.base.id);
                }
                let hit = get_element_with_transform_handle_type(
                    &refs, &selected, x, y, zoom, pointer, &map, &editor,
                );
                let expected = if p["hit"].is_null() {
                    None
                } else {
                    Some((
                        p["hit"]["element"].as_str().expect("id").to_string(),
                        handle_type(&p["hit"]["handle"]).expect("a handle"),
                    ))
                };
                assert_eq!(
                    hit.map(|(e, h)| (e.base.id.clone(), h)),
                    expected,
                    "{context}: getElementWithTransformHandleType"
                );
            }
        }
    }
}

