// -- resize.test.tsx ------------------------------------------------------------------

fn final_state(id: &str) -> Vec<Value> {
    replay(&case(id)).pop().expect("a step")
}

fn close(a: f64, b: f64) -> bool {
    (a - b).abs() < 0.005
}

fn xywh(e: &Value) -> [f64; 4] {
    [
        num(&e["x"]),
        num(&e["y"]),
        num(&e["width"]),
        num(&e["height"]),
    ]
}

fn assert_close(actual: [f64; 4], expected: [f64; 4], context: &str) {
    for i in 0..4 {
        assert!(
            close(actual[i], expected[i]),
            "{context}: {actual:?} != {expected:?}"
        );
    }
}

/// "generic element resizes with handle $handle" and "flips while resizing
/// with handle $handle" (resize.test.tsx:87-143).
#[test]
fn generic_element_resizes_and_flips() {
    let resizes = [
        ("n", [0.0, -27.0, 200.0, 127.0]),
        ("e", [0.0, 0.0, 267.0, 100.0]),
        ("s", [0.0, 0.0, 200.0, 61.0]),
        ("w", [20.0, 0.0, 180.0, 100.0]),
        ("ne", [0.0, -33.0, 205.0, 133.0]),
        ("se", [0.0, 0.0, 170.0, 19.0]),
        ("sw", [37.0, 0.0, 163.0, 125.0]),
        ("nw", [-34.0, 42.0, 234.0, 58.0]),
    ];
    let flips = [
        ("n", [0.0, 100.0, 200.0, 39.0]),
        ("e", [-45.0, 0.0, 45.0, 100.0]),
        ("s", [0.0, -110.0, 200.0, 110.0]),
        ("w", [200.0, 0.0, 41.0, 100.0]),
        ("ne", [-50.0, 100.0, 50.0, 25.0]),
        ("se", [-83.0, 0.0, 83.0, 42.0]),
        ("sw", [40.0, -23.0, 160.0, 23.0]),
        ("nw", [200.0, 100.0, 70.0, 33.0]),
    ];
    for (name, table) in [("resize", resizes), ("flip", flips)] {
        for (handle, expected) in table {
            let id = format!("upstream-generic-{name}-{handle}");
            let state = final_state(&id);
            assert_close(xywh(&state[0]), expected, &id);
            assert_eq!(num(&state[0]["angle"]), 0.0);
        }
    }
}

/// "resizes with locked aspect ratio" and "resizes from center"
/// (resize.test.tsx:145-187).
#[test]
fn generic_element_aspect_ratio_and_center() {
    let states = replay(&case("upstream-generic-aspect"));
    assert_close(xywh(&states[1][0]), [0.0, 0.0, 300.0, 150.0], "se shift");
    assert_close(xywh(&states[3][0]), [50.0, 50.0, 200.0, 100.0], "n shift");
    let states = replay(&case("upstream-generic-center"));
    assert_close(xywh(&states[1][0]), [20.0, 10.0, 160.0, 80.0], "nw alt");
    assert_close(xywh(&states[3][0]), [5.0, 10.0, 190.0, 80.0], "e alt");
}

/// "resizes with a label" (resize.test.tsx:213-240): the label stays
/// centred at font size 20.
#[test]
fn generic_element_label_stays_centred() {
    for state in replay(&case("upstream-generic-label"))
        .iter()
        .skip(1)
        .step_by(2)
    {
        let [rx, ry, rw, rh] = xywh(&state[0]);
        let [lx, ly, lw, lh] = xywh(&state[1]);
        assert!(close(lx + lw / 2.0, rx + rw / 2.0));
        assert!(close(ly + lh / 2.0, ry + rh / 2.0));
        assert_eq!(num(&state[1]["fontSize"]), 20.0);
    }
}

/// "%s with a label flips horizontally while resizing (proportional: %s)"
/// (resize.test.tsx:242-279).
#[test]
fn labelled_containers_flip() {
    for ty in ["rectangle", "ellipse", "diamond"] {
        for proportional in [false, true] {
            let id = format!(
                "upstream-{ty}-label-flip-{}",
                if proportional { "proportional" } else { "free" }
            );
            let state = final_state(&id);
            let [x, y, w, h] = xywh(&state[0]);
            assert_close(
                [x, y, w, h],
                [-300.0, 0.0, 300.0, if proportional { 150.0 } else { 100.0 }],
                &id,
            );
            let [lx, ly, lw, lh] = xywh(&state[1]);
            assert!((lx + lw / 2.0 - (x + w / 2.0)).abs() < 0.5, "{id}");
            assert!((ly + lh / 2.0 - (y + h / 2.0)).abs() < 0.5, "{id}");
            assert_eq!(num(&state[1]["angle"]), 0.0);
            let font_size = num(&state[1]["fontSize"]);
            if proportional {
                assert!(font_size > 20.0, "{id}");
            } else {
                assert_eq!(font_size, 20.0, "{id}");
            }
        }
    }
}

/// "keeps the flipped corner anchored while wrapped text sets the minimum
/// height" (resize.test.tsx:311-350).
#[test]
fn flipped_corner_stays_anchored() {
    let states = replay(&case("upstream-flipped-corner-anchored"));
    let mut min_height = 0.0;
    for (state, next_height) in states[1..].iter().zip([-10.0, -40.0, -80.0, -200.0]) {
        let [x, y, _, h] = xywh(&state[0]);
        let [_, ly, _, lh] = xywh(&state[1]);
        assert_eq!(x, 0.0);
        assert_eq!(y + h, 0.0);
        assert!(ly > y && ly + lh < y + h);
        if next_height == -10.0 {
            min_height = h;
            assert!(min_height > 80.0);
        }
        assert_eq!(h, f64::max(min_height, -next_height));
    }
}

/// "image element" (resize.test.tsx:917-973).
#[test]
fn images_resize_proportionally_and_flip() {
    let state = final_state("upstream-image-resize");
    assert_close(xywh(&state[0]), [0.0, -30.0, 130.0, 130.0], "resize");
    assert_eq!(state[0]["scale"], serde_json::json!([1, 1]));
    let state = final_state("upstream-image-flip");
    assert_close(xywh(&state[0]), [100.0, -50.0, 50.0, 50.0], "flip");
    assert_eq!(state[0]["scale"], serde_json::json!([-1, -1]));
    let states = replay(&case("upstream-image-aspect"));
    assert_close(xywh(&states[1][0]), [0.0, -30.0, 130.0, 130.0], "locked");
    assert_close(xywh(&states[3][0]), [0.0, 20.0, 100.0, 80.0], "unlocked");
    let state = final_state("upstream-image-center");
    assert_close(xywh(&state[0]), [15.0, 15.0, 70.0, 70.0], "center");
}

/// "text element" (resize.test.tsx:721-915): side handles rewrap without
/// changing the font; corners scale it.
#[test]
fn text_resizes_and_rewraps() {
    let before = case("upstream-text-resize")["elements"][0].clone();
    let [_, _, width, height] = xywh(&before);
    let state = final_state("upstream-text-resize");
    let t = &state[0];
    let scale = 40.0 / height + 1.0;
    assert_close(xywh(t), [0.0, 0.0, width * scale, height * scale], "se");
    assert!(close(num(&t["fontSize"]), num(&before["fontSize"]) * scale));

    let states = replay(&case("upstream-text-e"));
    assert_eq!(xywh(&states[1][0])[2], 130.0);
    assert_eq!(xywh(&states[3][0])[2], 100.0);

    let states = replay(&case("upstream-text-wraps"));
    let original = case("upstream-text-wraps")["elements"][0].clone();
    let w = states[1][0].clone();
    assert_eq!(num(&w["width"]), num(&original["width"]) - 50.0);
    assert!(num(&w["height"]) > num(&original["height"]));
    assert_ne!(w["text"], original["text"]);
    assert_eq!(w["autoResize"], false);
    assert_eq!(states[3][0]["text"], original["text"]);
    assert_eq!(states[3][0]["height"], original["height"]);
}

/// "multiple selection resizes with generic elements"
/// (resize.test.tsx:1032-1091).
#[test]
fn multiple_generic_elements_scale_together() {
    let state = final_state("upstream-multi-generic");
    let scale = f64::max(1.0 + 50.0 / 220.0, 1.0 + 30.0 / 160.0);
    assert_close(
        xywh(&state[0]),
        [0.0, 0.0, 100.0 * scale, 80.0 * scale],
        "rectangle",
    );
    assert!(close(num(&state[1]["fontSize"]), 20.0 * scale));
    assert_close(
        xywh(&state[2]),
        [140.0 * scale, 40.0 * scale, 80.0 * scale, 80.0 * scale],
        "diamond",
    );
    assert_close(
        xywh(&state[3]),
        [40.0 * scale, 100.0 * scale, 80.0 * scale, 60.0 * scale],
        "ellipse",
    );
}

/// "multiple selection flips while resizing" (resize.test.tsx:1454-1559).
#[test]
fn multiple_selection_flips() {
    let state = final_state("upstream-multi-flip");
    let scale_x = -800.0 / 380.0 + 1.0;
    let scale_y = -scale_x;
    let image = &state[0];
    assert_close(
        xywh(image),
        [
            160.0 * scale_x,
            100.0 * scale_y,
            100.0 * -scale_x,
            100.0 * scale_y,
        ],
        "image",
    );
    assert!(close(
        num(&image["angle"]),
        std::f64::consts::PI * 5.0 / 6.0
    ));
    assert_eq!(image["scale"], serde_json::json!([-1, 1]));
    let rectangle = &state[2];
    assert_eq!(num(&rectangle["angle"]), std::f64::consts::PI * 11.0 / 6.0);
    // the arrow drawn from (380, 240) by (-60, -80) is mirrored across the
    // anchor and scaled with everything else
    let arrow = state.iter().find(|e| e["type"] == "arrow").expect("arrow");
    assert!(close(num(&arrow["points"][1][0]), 60.0 * scale_y));
    assert!(close(num(&arrow["points"][1][1]), -80.0 * scale_y));
}

/// "flips the fixed point binding on negative resize for group selection"
/// (resize.test.tsx:693-718): an elbow arrow resized with its start target
/// mirrors the fixed point.
#[test]
fn elbow_fixed_point_mirrors_on_group_flip() {
    let state = final_state("upstream-elbow-fixed-point-group");
    let arrow = state.iter().find(|e| e["type"] == "arrow").expect("arrow");
    let fixed = &arrow["startBinding"]["fixedPoint"];
    assert!((num(&fixed[0]) - (1.0 - 1.0526315789473684)).abs() < 1e-9);
    assert!((num(&fixed[1]) - 0.25).abs() < 1e-9);
}

/// Rotation: 15 degree steps with Shift (`SHIFT_LOCKING_ANGLE`), labels
/// turn with their container, and a lone elbow arrow or a selection with a
/// frame is not rotated.
#[test]
fn rotation_snaps_and_is_refused_where_upstream_refuses() {
    let states = replay(&case("rotate-single-discrete"));
    let step = std::f64::consts::PI / 12.0;
    for state in &states[1..] {
        let angle = num(&state[0]["angle"]);
        assert!(
            ((angle / step).round() * step - angle).abs() < 1e-9,
            "{angle}"
        );
        assert_eq!(state[1]["angle"], state[0]["angle"]);
    }
    let c = case("frame-rotate-multi-refused");
    assert_eq!(c["steps"][1]["result"], false);
    let c = case("elbow-single-refused");
    assert_eq!(c["steps"][1]["result"], false);
    replay(&case("frame-rotate-multi-refused"));
    replay(&case("elbow-single-refused"));
}

/// A sticky note's label keeps its layout through a resize: the port asks
/// for the layout with the intents upstream derives
/// (`getStickyNoteResizeIntent`) and the minimum size
/// (`getStickyNoteMinSize`).
#[test]
fn sticky_notes_ask_for_their_layout() {
    for id in [
        "sticky-corner",
        "sticky-edge-e",
        "sticky-edge-n",
        "sticky-flip",
        "sticky-multi",
    ] {
        let c = case(id);
        let asked = c["steps"]
            .as_array()
            .expect("steps")
            .iter()
            .flat_map(|s| s["hooks"].as_array().into_iter().flatten())
            .any(|h| h["hook"] == "stickyNoteLayout");
        assert!(asked, "{id}: no layout asked");
        replay(&c);
    }
}

/// The handle sizes by pointer type (`transformHandles.ts:49-53`) and the
/// gap to the rotation handle (`:55`).
#[test]
fn handle_sizes_by_pointer_type() {
    use excali_editor::transform_handles::{transform_handle_size, ROTATION_RESIZE_HANDLE_GAP};
    assert_eq!(transform_handle_size(PointerType::Mouse), 8.0);
    assert_eq!(transform_handle_size(PointerType::Pen), 16.0);
    assert_eq!(transform_handle_size(PointerType::Touch), 28.0);
    assert_eq!(ROTATION_RESIZE_HANDLE_GAP, 16.0);
    let r = element(&case("handles-00-rectangle")["elements"][0]);
    let map = ElementsMap::new([&r]);
    let handles = get_transform_handles(&r, 1.0, &map, PointerType::Touch, &OmitSides::default());
    assert_eq!(
        handles
            .get(TransformHandleType::Rotation)
            .expect("rotation")[2],
        28.0
    );
}
